style.css:
@-moz-document url-prefix("https://www.amazon."), url-prefix("https://smile.amazon."), url-prefix("https://amazon.") {
/* Hide ads */
	#cbcc_banner,
	#nav-upnav,
    #detail-ilm_div,
    #percolate-ui-ilm_feature_div,
    #sc-new-upsell,
    .mom-nudge-card-item {
		display: none;
	}

	/* Fade out sections unrelated to the current product, until hovered */
	#vtpsims:not(:hover),
	#rhf:not(:hover),
	#purchaseShvl:not(:hover),
	#sims_fbt:not(:hover),
	#purchase-sims-feature:not(:hover),
	#fallbacksessionShvl:not(:hover),
	#sp_detail:not(:hover),
	#sp_detail2:not(:hover) {
		opacity: 0.3;
	}
}
